package io.github.celerycore.kenjatime.nativeprototype;
import static org.junit.Assert.*;
import java.io.*;import java.nio.file.Files;import java.nio.charset.StandardCharsets;import java.util.*;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class ArchiveInstallTest {
 File dir;GameLibrary library;android.content.res.AssetManager assets;
 @Before public void setup()throws Exception{dir=Files.createTempDirectory("archive-test").toFile();library=new GameLibrary(dir);assets=RuntimeEnvironment.getApplication().getAssets();library.prepare(assets);}
 @After public void cleanup()throws Exception{try(java.util.stream.Stream<java.nio.file.Path> paths=Files.walk(dir.toPath())){paths.sorted(Comparator.reverseOrder()).forEach(path->path.toFile().delete());}}
 static ArchiveInstaller.Reader entries(String... entries){return new ArchiveInstaller.Reader(){int index=-2;ByteArrayInputStream in;public ArchiveInstaller.Entry next(){index+=2;if(index>=entries.length)return null;byte[] b=entries[index+1].getBytes(StandardCharsets.UTF_8);in=new ByteArrayInputStream(b);return new ArchiveInstaller.Entry(entries[index],b.length,32768,false);}public int read(byte[] b){return in.read(b,0,b.length);}public void close(){}};}
 ArchiveInstaller.Reader character(){return entries("\\Hero\\.\\Hero.DEF","[Info]\nname=Test Hero\n[Files]\nsprite=SPRITES/Hero.SFF\nanim=Hero.AIR","Hero/Sprites/Hero.SFF","sprite","Hero/Hero.AIR","[Begin Action 0]");}
 @Test public void archiveInstallsPersistsListsAndRemovesWithoutChangingBundledAssets()throws Exception{library.installArchive(character(),"cloud-download","any",assets,m->{});GameCatalog c=new GameCatalog(library.root());JSONObject data=c.read();assertEquals(2,data.getJSONArray("characters").length());assertTrue(data.getJSONArray("characters").getJSONObject(1).getString("sprite").endsWith("hero/sprites/hero.sff"));String pkg=data.getJSONArray("packages").getJSONObject(0).getString("id");library.prepare(assets);assertEquals(2,c.read().getJSONArray("characters").length());library.removePackage(pkg,assets);assertEquals(1,c.read().getJSONArray("characters").length());}
 @Test public void invalidAndStageOnlyImportsRollBack()throws Exception{for(ArchiveInstaller.Reader r:new ArchiveInstaller.Reader[]{entries("../bad","x"),entries("notes.txt","no character"),character()}){try{library.installArchive(r,"bad","stage",assets,m->{});fail();}catch(IOException expected){}}assertEquals(0,new GameCatalog(library.root()).read().getJSONArray("packages").length());}
 @Test public void pathsNormalizeWindowsSeparatorsAndRejectExternalDrives()throws Exception{assertEquals("hero/a.def",ArchiveInstaller.path("/Hero/sub/../A.DEF"));for(String path:new String[]{"../escape","C:\\outside","x/../../escape","bad\u0000name"})try{ArchiveInstaller.path(path);fail(path);}catch(IOException expected){}}
 @Test public void duplicateContentsMustMatchAndActualBytesStayWithinBudget()throws Exception{File target=new File(dir,"target");target.mkdir();ArchiveInstaller.extract(entries("A","same","a","same"),target,100,3,m->{});try{ArchiveInstaller.extract(entries("A","different"),target,100,3,m->{});fail();}catch(IOException expected){}try{ArchiveInstaller.extract(entries("large","12345"),target,4,3,m->{});fail();}catch(IOException expected){}}
 @Test public void linksCannotBeInstalled()throws Exception{ArchiveInstaller.Reader r=new ArchiveInstaller.Reader(){public ArchiveInstaller.Entry next(){return new ArchiveInstaller.Entry("link",0,32768,true);}public int read(byte[] b){return 0;}public void close(){}};try{library.installArchive(r,"link","any",assets,m->{});fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("links"));}}
 @Test public void catalogValidatesMatchIdsAndPreservesAiPaletteAndTrainingSettings()throws Exception{GameCatalog c=new GameCatalog(library.root());JSONObject request=new JSONObject().put("character","chars/kfm_zss/kfm_zss.def").put("stage","stages/kenjatime-grid.def").put("mode","training").put("palette",9);List<String> args=Arrays.asList(c.matchArguments(request));assertEquals("9",args.get(args.indexOf("-p1.color")+1));assertEquals("-1",args.get(args.indexOf("-time")+1));assertFalse(args.contains("-loadmotif"));request.put("character","../../outside");try{c.matchArguments(request);fail();}catch(IOException expected){}}
 @Test public void matchHandoffWorksWithoutAndroidArgvAndForcesKenjatimeBootstrap()throws Exception{org.json.JSONObject r=new org.json.JSONObject().put("character","chars/kfm_zss/kfm_zss.def").put("stage","stages/kenjatime-grid.def").put("mode","training");library.prepareMatch(r,assets);org.json.JSONObject flags=new org.json.JSONObject(GameCatalog.text(new File(library.root(),"save/kenjatime-match.json")));assertEquals("chars/kfm_zss/kfm_zss.def",flags.getString("-p1"));assertEquals("training",flags.getString("-kenjatime-mode"));assertTrue(GameCatalog.text(new File(library.root(),"save/config.ini")).contains("System = data/kenjatime/engine.lua"));}
 @Test public void invalidMatchCannotReplaceTheLastValidatedSelection()throws Exception{org.json.JSONObject r=new org.json.JSONObject().put("character","chars/kfm_zss/kfm_zss.def").put("stage","stages/kenjatime-grid.def");library.prepareMatch(r,assets);String before=GameCatalog.text(new File(library.root(),"save/kenjatime-match.json"));r.put("character","../../outside.def");try{library.prepareMatch(r,assets);fail();}catch(IOException expected){}assertEquals(before,GameCatalog.text(new File(library.root(),"save/kenjatime-match.json")));}
 @Test public void relocatedStageMusicUsesPrivateCopyAndKeepsOriginalAndCatalog()throws Exception{
  String original="[Info]\nname=Forest\n[Music]\nbgmusic=sound/Blood heat!.mp3\nround2.bgm=../sound/next.ogg\n[BGDef]\nspr=forest.sff";
  library.installArchive(entries("stages/forest.def",original,"stages/blood heat!.mp3","mp3","sound/next.ogg","ogg","stages/forest.sff","sprite"),"forest.rar","stage",assets,m->{});
  JSONObject before=new GameCatalog(library.root()).read();String stage=before.getJSONArray("stages").getJSONObject(1).getString("id");
  List<String> args=Arrays.asList(library.prepareMatch(new JSONObject().put("character","chars/kfm_zss/kfm_zss.def").put("stage",stage),assets));String copy=args.get(args.indexOf("-s")+1),text=GameCatalog.text(new File(library.root(),copy));
  assertTrue(copy.endsWith(".kenjatime-stage.def"));assertTrue(text.contains("bgmusic="+stage.replace("forest.def","blood heat!.mp3")));assertTrue(text.contains("/sound/next.ogg"));assertTrue(text.contains("spr=forest.sff"));assertEquals(original,GameCatalog.text(new File(library.root(),stage)));assertEquals(2,new GameCatalog(library.root()).read().getJSONArray("stages").length());
 }
}
